package com.printflow.customer;

import com.printflow.identity.*;import jakarta.validation.constraints.*;import java.util.*;import java.time.*;
import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;
import tools.jackson.databind.json.JsonMapper;

@Service public class RazorpayPayments {
 public record Create(@NotNull UUID quoteId,@NotBlank @Pattern(regexp="ADVANCE|BALANCE") String purpose){}
 public record Verify(@NotBlank @Pattern(regexp="order_[A-Za-z0-9]+") String orderId,@NotBlank @Pattern(regexp="pay_[A-Za-z0-9]+") String paymentId,@NotBlank @Size(max=128) String signature){}
 private final JdbcTemplate db;private final Payments payments;private final RazorpayClient client;private final ProjectNotifications mail;private final JsonMapper json;private final com.printflow.shared.RequestLimits limits;
 public RazorpayPayments(JdbcTemplate db,Payments payments,RazorpayClient client,ProjectNotifications mail,JsonMapper json,com.printflow.shared.RequestLimits limits){this.db=db;this.payments=payments;this.client=client;this.mail=mail;this.json=json;this.limits=limits;}
 private ResponseStatusException conflict(String s){return new ResponseStatusException(HttpStatus.CONFLICT,s);}
 public Map<String,Object> status(){return Map.of("configured",client.configured(),"mode","TEST","webhooksConfigured",client.webhooks(),"liveEnabled",false);}
 private void customer(StaffPrincipal u,UUID id){if(!u.role().equals("CUSTOMER"))throw new ResponseStatusException(HttpStatus.FORBIDDEN);var rows=db.queryForList("select customer_user_id,status from enquiries where id=? for update",id);if(rows.isEmpty()||!u.id().equals(rows.getFirst().get("customer_user_id")))throw new NoSuchElementException();if("CLOSED".equals(rows.getFirst().get("status")))throw conflict("Contact the team to settle closed work");}
 @Transactional public Map<String,Object> create(StaffPrincipal u,UUID id,Create input){client.enabled();customer(u,id);limits.require("razorpay-order",u.id().toString(),10);var view=payments.view(u,id);if(!input.quoteId().toString().equals(view.get("quoteId").toString())||!Boolean.TRUE.equals(view.get("policyCurrent")))throw conflict("Confirm the current accepted quotation and payment terms first");if(db.queryForObject("select exists(select 1 from quote_versions where enquiry_id=? and state='ISSUED')",Boolean.class,id))throw conflict("Resolve the pending quotation amendment before online payment");@SuppressWarnings("unchecked") var policy=(Map<String,Object>)view.get("policy");long paid=((Number)view.get("paidPaise")).longValue(),balance=((Number)view.get("balancePaise")).longValue();long amount=input.purpose().equals("ADVANCE")?Math.max(0,((Number)policy.get("advance_paise")).longValue()-paid):balance;if(amount<100)throw conflict("No payable amount of at least INR 1 remains for this selection");
  // Reuse an unpaid order with the exact same immutable agreement, policy and amount.
  var old=db.queryForList("select g.* from gateway_orders g where g.enquiry_id=? and g.quote_id=? and g.policy_id=? and g.amount_paise=? and g.purpose=? and not exists(select 1 from gateway_captures c where c.order_id=g.id) order by g.created_at desc limit 1",id,input.quoteId(),policy.get("id"),amount,input.purpose());if(!old.isEmpty())return checkout(old.getFirst());UUID order=UUID.randomUUID();var remote=client.order(amount,order.toString());String provider=String.valueOf(remote.get("id"));if(!provider.matches("order_[A-Za-z0-9]+")||!"INR".equals(remote.get("currency"))||!(remote.get("amount") instanceof Number n)||n.longValue()!=amount)throw conflict("Provider returned an unexpected order");db.update("insert into gateway_orders(id,enquiry_id,quote_id,policy_id,requested_by,provider_order,amount_paise,purpose) values(?,?,?,?,?,?,?,?)",order,id,input.quoteId(),policy.get("id"),u.id(),provider,amount,input.purpose());return Map.of("keyId",client.key(),"orderId",provider,"amountPaise",amount,"currency","INR","mode","TEST");
 }
 private Map<String,Object> checkout(Map<String,Object> o){return Map.of("keyId",client.key(),"orderId",o.get("provider_order"),"amountPaise",o.get("amount_paise"),"currency","INR","mode","TEST");}
 @Transactional public Map<String,Object> verify(StaffPrincipal u,UUID id,Verify input){client.enabled();customer(u,id);limits.require("razorpay-verify",u.id().toString(),30);var o=order(input.orderId());if(!id.equals(o.get("enquiry_id")))throw new NoSuchElementException();if(!client.checkoutSignature(input.orderId(),input.paymentId(),input.signature()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Payment signature did not match");capture(o,input.paymentId());return payments.view(u,id);}
 private Map<String,Object> order(String provider){var rows=db.queryForList("select * from gateway_orders where provider_order=?",provider);if(rows.isEmpty())throw new NoSuchElementException();return rows.getFirst();}
 /** A signed webhook is additionally reconciled against the provider API; duplicate events add no receipt. */
 @Transactional public void webhook(byte[] body,String signature){client.enabled();if(!client.webhookSignature(body,signature))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid webhook signature");var tree=json.readTree(body);if(!tree.path("event").asText().equals("payment.captured"))return;var payment=tree.path("payload").path("payment").path("entity");String orderId=payment.path("order_id").asText(),paymentId=payment.path("id").asText();var o=order(orderId);db.queryForObject("select id from enquiries where id=? for update",UUID.class,o.get("enquiry_id"));capture(o,paymentId);}
 private void capture(Map<String,Object> o,String paymentId){UUID id=(UUID)o.get("enquiry_id");var existing=db.queryForList("select order_id from gateway_captures where provider_payment=?",paymentId);if(!existing.isEmpty()){if(!o.get("id").equals(existing.getFirst().get("order_id")))throw conflict("Payment is already allocated elsewhere");return;}if(db.queryForObject("select exists(select 1 from gateway_captures where order_id=?)",Boolean.class,o.get("id")))throw conflict("This order already has a different captured payment");var remote=client.payment(paymentId);if(!paymentId.equals(remote.get("id"))||!o.get("provider_order").equals(remote.get("order_id"))||!"INR".equals(remote.get("currency"))||!"captured".equals(remote.get("status"))||!Boolean.TRUE.equals(remote.get("captured"))||!(remote.get("amount") instanceof Number n)||n.longValue()!=((Number)o.get("amount_paise")).longValue()||remote.get("amount_refunded") instanceof Number refunded&&refunded.longValue()>0)throw conflict("Razorpay has not confirmed the expected captured payment");
  UUID receipt=UUID.randomUUID();db.update("insert into payment_receipts(id,enquiry_id,quote_id,amount_paise,method,reference,paid_on,actor_id) values(?,?,?,?,'RAZORPAY_TEST',?,?,?)",receipt,id,o.get("quote_id"),o.get("amount_paise"),paymentId,LocalDate.now(ZoneId.of("Asia/Kolkata")),o.get("requested_by"));db.update("insert into gateway_captures(provider_payment,order_id,receipt_id) values(?,?,?)",paymentId,o.get("id"),receipt);String text="Razorpay TEST payment confirmed: INR "+Payments.money(((Number)o.get("amount_paise")).longValue())+". No real money moved. See the test receipt and updated balance in your workspace.";db.update("insert into work_events(id,enquiry_id,actor_id,kind,message) values(?,?,?,'PAYMENT_RECEIVED',?)",receipt,id,o.get("requested_by"),text);mail.both(id,"PAYMENT_RECEIVED",receipt,text);
 }
}
